def is_conflicting(self) -> bool:
    """If installed version conflicts with required version."""
    # unknown installed version is also considered conflicting
    if self.is_missing:
        return True

    from packaging.version import parse
    try:
        installed_version = parse(self.installed_version)
        return not self._obj.specifier.contains(installed_version, prereleases=True)
    except ValueError:
        # If we can't parse the version, consider it a conflict
        return True

